package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;import static com.bridge.quartercore.NativeSheetsModel.*;
class FixedEOverallV2RunnerTest {
 static FixedEOverallV2Runner runner(JournaledNativeWriterTest.Memory m,FixedERestartClockSafetyTest.Time clock,java.util.function.Consumer<JournalQuarterAuthority> hook){var ordinary=new AtomicReference<JournalSessionAuthority>();var channels=FixedERestartClockSafetyTest.channels(FixedERestartClock.binding(),m,ordinary,hook);return new FixedEOverallV2Runner(m::snapshot,new PlannedMaintenanceStartupFactory.Channels(){public PlannedMaintenanceStartupFactory.Channel ordinary(JournalSessionAuthority a){throw new AssertionError("No ordinary channel");}public PlannedMaintenanceStartupFactory.Channel quarter(JournalQuarterAuthority a){return channels.quarter(a);}},clock);}
 @Test void realPinnedFivePhaseFoldAndArtifactMatchIndependentConstants(){var base=FixedEOverallV2Runner.baseline();assertEquals(FixedEOverallV2Runner.TOKEN,JournalSessionAuthority.fullToken(base));var m=new JournaledNativeWriterTest.Memory(base);var clock=new FixedERestartClockSafetyTest.Time();var r=runner(m,clock,q->assertSame(clock,q.securityClock()));r.arm();assertEquals(0,m.writes);r.run();assertEquals(5,m.writes);assertEquals(29,NativeCommitJournal.verify(FixedERestartClock.binding().manualBinding(),m.b,FixedEOverallV2Runner.businessClock()).sequence());FixedEOverallV2Runner.verifyExpected(base,m.b);assertEquals(JournalSessionAuthority.fullToken(m.b),r.verifiedToken());assertEquals(r.verifiedToken(),parse(new String(r.verifiedArtifact(),java.nio.charset.StandardCharsets.UTF_8)).path("fullToken").asText());assertThrows(RuntimeException.class,r::run);assertThrows(RuntimeException.class,()->runner(m,clock,q->{}).arm());assertEquals(5,m.writes);}
 @Test void eachUnknownPhaseStopsWithoutReplayAndNoArtifact(){for(int phase=1;phase<=5;phase++)for(boolean apply:List.of(false,true)){int at=phase;var m=new JournaledNativeWriterTest.Memory(FixedEOverallV2Runner.baseline()){@Override public void batch(String wire){if(writes+1==at){if(apply)super.batch(wire);else writes++;throw new Unknown();}super.batch(wire);}};var r=runner(m,new FixedERestartClockSafetyTest.Time(),q->{});r.arm();assertThrows(RuntimeException.class,r::run);assertEquals(at,m.writes);assertThrows(RuntimeException.class,r::run);assertThrows(RuntimeException.class,r::verifiedArtifact);assertEquals(at,m.writes);}}
 @Test void tamperSecurityExpiryRollbackAndCancellationHaveZeroWrites(){for(int mode=0;mode<4;mode++){var m=new JournaledNativeWriterTest.Memory(FixedEOverallV2Runner.baseline());var clock=new FixedERestartClockSafetyTest.Time();int fault=mode;var ref=new AtomicReference<FixedEOverallV2Runner>();var r=runner(m,clock,q->{if(fault==0)clock.now=clock.now.plusSeconds(301);else if(fault==1)clock.now=clock.now.minusSeconds(1);else if(fault==2)ref.get().close();else Thread.currentThread().interrupt();});ref.set(r);r.arm();try{assertThrows(RuntimeException.class,r::run);assertEquals(0,m.writes);}finally{Thread.interrupted();}}var m=new JournaledNativeWriterTest.Memory(FixedEOverallV2Runner.baseline());m.b.sheet("accounts").rows.get(1).set(1,"1");assertThrows(RuntimeException.class,()->runner(m,new FixedERestartClockSafetyTest.Time(),q->{}).arm());assertEquals(0,m.writes);}
 @Test void defaultOffScopeCannotUseFormalOrWrongBusinessClock(){assertThrows(RuntimeException.class,()->FixedEOverallV2Main.requireConfiguration(Map.of()));assertThrows(RuntimeException.class,()->FixedEOverallV2Runner.requireScope(new ManualQuarterMaintenance.Binding("formal-sheet",UUID.randomUUID().toString(),"bridgego-managed"),FixedEOverallV2Runner.businessClock()));assertThrows(RuntimeException.class,()->FixedEOverallV2Runner.requireScope(FixedERestartClock.binding().manualBinding(),java.time.Clock.systemUTC()));assertNull(NativeRestartCompiledRelease.current());}
}
